sys_script_include.script:
var EventUtils = Class.create();
EventUtils.prototype = {
    initialize: function() {
        this._eventTable = 'x_1610434_event_0_event_record';
    },

    getEventDetails: function(_eventId) {
        var _eventGR = new GlideRecordSecure(this._eventTable);
        _eventGR.addQuery('sys_id', _eventId);
        _eventGR.query();
        if (_eventGR.next()) {
            return this._mapEventFields(_eventGR);
        }
        return null;
    },

    isEventVIP: function(_eventId) {
        var _eventGR = new GlideRecordSecure(this._eventTable);
        _eventGR.addQuery('sys_id', _eventId);
        _eventGR.query();
        if (_eventGR.next()) {
            return _eventGR.vip.toString() == 'true';
        }
        return false;
    },

    calculateRemainingBudget: function(_eventId) {
        return new BudgetUtils().calculateRemainingBudget(_eventId);
    },

    getEventTasks: function(_eventId) {
        return new TaskUtils().getTasksForEvent(_eventId);
    },

    getEventAttendees: function(_eventId) {
        return new AttendeeUtils().getAttendeesByEvent(_eventId);
    },

    getEventVendors: function(_eventId) {
        return new VendorUtils().getVendorsByEvent(_eventId);
    },

    getEventBudgetDetails: function(_eventId) {
        return new BudgetUtils().getBudgetDetailsByEvent(_eventId);
    },

    getEventFeedback: function(_eventId) {
        return new FeedbackUtils().getFeedbackByEvent(_eventId);
    },

    _mapEventFields: function(_eventGR) {
        return {
            sysId: _eventGR.getUniqueValue(),
            eventName: _eventGR.getValue('event_name'),
            eventDate: _eventGR.getValue('event_date'),
            location: _eventGR.getValue('location'),
            vip: _eventGR.vip.toString() == 'true',
            status: _eventGR.getValue('status')
        };
    },

    type: 'EventUtils'
};
